SourceCode.Declaration:
/// <summary>
/// CB748_PricingConditions
/// </summary>
internal final class METPendingVendorInvoiceOffRemittanceRebate
{
    VendInvoiceInfoTable vendInvoiceInfoTable;

}

Method.Source:
/// <summary>
/// New method
/// </summary>
/// <param name = "_vendInvoiceInfoTable">Pending vendor invoice header</param>
protected void new(VendInvoiceInfoTable _vendInvoiceInfoTable)
{
    vendInvoiceInfoTable = _vendInvoiceInfoTable;
}

/// <summary>
/// Construct
/// </summary>
/// <param name = "_vendInvoiceInfoTable">Pending vendor invoice header</param>
/// <returns>New instance of <c>METPendingVendorInvoiceOffRemittanceRebate</c></returns>
public static METPendingVendorInvoiceOffRemittanceRebate construct(VendInvoiceInfoTable _vendInvoiceInfoTable)
{        
    return new METPendingVendorInvoiceOffRemittanceRebate(_vendInvoiceInfoTable);
}

/// <summary>
/// Run method
/// </summary>
public void run()
{        
    #OCCRetryCount

    if (this.validate())
    {
        try
        {
            ttsbegin;
            this.process();
            ttscommit;
        }
        catch (Exception::Deadlock)
        {
            retry;
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() == 0)
            {
                if (xSession::currentRetryCount() >= #RetryNum)
                {
                    throw Exception::UpdateConflictNotRecovered;
                }
                else
                {
                    retry;
                }
            }
            else
            {
                throw Exception::UpdateConflict;
            }
        }
    }    
}

/// <summary>
/// Create rebate charge codes
/// </summary>
protected void process()
{
    boolean isRebateChargeCode = this.createRebateChargeCodes();   

    // set invoice on hold if parameter is ticked
    if (!isRebateChargeCode && METVendParameters::find().HoldInvoice)
    {
        vendInvoiceInfoTable.selectForUpdate(true);
        vendInvoiceInfoTable.Hold = NoYes::Yes;
        vendInvoiceInfoTable.update();
    }
}

/// <summary>
/// Validate
/// </summary>
/// <returns>True if validation successful; otherwise, false.</returns>
protected boolean validate()
{
    boolean ret = false;

    //only apply off remittance rebates if Enable vendor rebates parameter is yes
    if (METVendParameters::find().VendorRebatesEnabled
    && !vendInvoiceInfoTable.METReturnInvoice)
    {
        ret = true;
    }

    return ret;
}

/// <summary>
/// Create rebate charge codes for all pending vendor invoice lines
/// </summary>
/// <returns>True if rebate charge codes created; otherwise, false.</returns>
boolean createRebateChargeCodes()
{
    VendInvoiceInfoLine vendInvoiceInfoLine;
    int countChargesBeforeRebate, countChargesAfterRebate;
    boolean isRebateChargeCode = false;

    // Loop through lines
    while select vendInvoiceInfoLine
           where vendInvoiceInfoLine.ParmId     == vendInvoiceInfoTable.ParmId
              && vendInvoiceInfoLine.TableRefId == vendInvoiceInfoTable.TableRefId
    {
        // Count vendor invoice line charges
        if (!isRebateChargeCode)
        {
            countChargesBeforeRebate = MarkupTrans::METCountCharges(tableNum(VendInvoiceInfoLine), vendInvoiceInfoLine.RecId);
        }

        // Trigger the new auto charge lines using the new logic (copied from vendInvoiceInfoLine\createMarkupTrans) and new parameter _metRebateCodes = true
        Markup::METInsertMarkupTrans(HeadingLine::Line,
                          MarkupModuleType::Vend,
                          vendInvoiceInfoLine,
                          vendInvoiceInfoTable.InvoiceAccount,
                          vendInvoiceInfoTable.MarkupGroup,
                          vendInvoiceInfoTable.CurrencyCode,
                          vendInvoiceInfoTable.vendTable_InvoiceAccount().languageId(),
                          vendInvoiceInfoLine.ItemId,
                          vendInvoiceInfoLine.inventTable().purchMarkupGroup(),
                         (vendInvoiceInfoLine.LineAmount < 0), // invert sign on creditnotes
                          false); // Added _deleteExistingMarkupTrans = false so it doesn't remove charge codes copied from PO at creation or non rebate charge codes

        // Count vendor invoice line charges
        if (!isRebateChargeCode)
        {
            countChargesAfterRebate = MarkupTrans::METCountCharges(tableNum(VendInvoiceInfoLine), vendInvoiceInfoLine.RecId);

            if (countChargesAfterRebate > countChargesBeforeRebate)
            {
                isRebateChargeCode = true;
            }
        }
    }

    return isRebateChargeCode;
}
